from __future__ import print_function
import errno
import os
import stat

base = b'/srv/legacy2/filename-encoding-migration'
src_root = os.path.join(base, b'imported')
dst_root = os.path.join(base, b'converted')
report_path = os.path.join(base, b'collision-report.txt')
collisions = []
copied = []

def convert_component(name):
    return name.decode('iso-8859-1').encode('utf-8')

def convert_rel(rel):
    if rel in (b'', b'.'):
        return b''
    return os.path.join(*[convert_component(x) for x in rel.split(os.sep)])

def display_latin1(path):
    return path.decode('iso-8859-1')

def display_utf8(path):
    return path.decode('utf-8')

for root, dirs, files in os.walk(src_root, topdown=True, followlinks=False):
    rel = os.path.relpath(root, src_root)
    dst_dir = os.path.join(dst_root, convert_rel(rel))
    if os.path.exists(dst_dir) and not os.path.isdir(dst_dir):
        collisions.append('DIRECTORY COLLISION: source=%s destination=%s' %
                          (display_latin1(root), display_utf8(dst_dir)))
        dirs[:] = []
        continue
    if not os.path.isdir(dst_dir):
        os.makedirs(dst_dir)
    for name in files:
        source = os.path.join(root, name)
        destination = os.path.join(dst_dir, convert_component(name))
        try:
            fd = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except OSError as exc:
            if exc.errno == errno.EEXIST:
                collisions.append('FILE COLLISION: source=%s destination=%s' %
                                  (display_latin1(source), display_utf8(destination)))
                continue
            raise
        try:
            with open(source, 'rb') as sf, os.fdopen(fd, 'wb') as df:
                fd = None
                while True:
                    block = sf.read(1024 * 1024)
                    if not block:
                        break
                    df.write(block)
            st = os.stat(source)
            os.chmod(destination, stat.S_IMODE(st.st_mode))
            os.utime(destination, (st.st_atime, st.st_mtime))
            copied.append((source, destination))
        except Exception:
            if fd is not None:
                os.close(fd)
            try:
                os.unlink(destination)
            except OSError:
                pass
            raise

report_tmp = report_path + b'.tmp.' + str(os.getpid()).encode('ascii')
with open(report_tmp, 'wb') as rf:
    rf.write(('Filename migration collision report\n'
              'Source encoding: ISO-8859-1\n'
              'Destination encoding: UTF-8\n'
              'Policy: existing destinations are never overwritten\n').encode('utf-8'))
    if collisions:
        for line in collisions:
            rf.write((line + '\n').encode('utf-8'))
    else:
        rf.write(b'No collisions\n')
os.rename(report_tmp, report_path)

for source, destination in copied:
    print('COPIED: %s -> %s' % (display_latin1(source), display_utf8(destination)))
for line in collisions:
    print(line)
print('SUMMARY: copied=%d collisions=%d report=%s' %
      (len(copied), len(collisions), display_utf8(report_path)))
